CREATE TYPE "curso" AS ENUM (
	'ciencia da computacao',
	'engenharia de software',
	'analise de sistemas',
	'sistema da informacao'
);

CREATE TYPE "periodo" AS ENUM (
	'matutino',
	'noturno'
);

CREATE TABLE IF NOT EXISTS "usuario" (
	-- Identificador do usuario
	-- 
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(255) NOT NULL,
	"email" VARCHAR(255),
	"senha" VARCHAR NOT NULL,
	"ativo" BOOLEAN NOT NULL,
	"data_nasc" DATE,
	"cpf" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON COLUMN "usuario"."id" IS 'Identificador do usuario
';

CREATE TABLE IF NOT EXISTS "aluno" (
	"ra" INTEGER NOT NULL UNIQUE,
	"usuario_id" INTEGER NOT NULL UNIQUE,
	"curso" CURSO NOT NULL,
	PRIMARY KEY("ra")
);

CREATE TABLE IF NOT EXISTS "disciplina" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(255) NOT NULL,
	"pertence_curso" CURSO ARRAY,
	"data_criacao" DATE NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "matricula" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"aluno_ra" INTEGER NOT NULL UNIQUE,
	"turma_id" INTEGER,
	"ano" INTEGER,
	"semestre" INTEGER,
	"presencial" BOOLEAN NOT NULL,
	"ativo" BOOLEAN NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "turma" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(255) NOT NULL,
	"data_criacao" TIME NOT NULL,
	"periodo" PERIODO NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "compoe" (
	"id_turma" INTEGER NOT NULL UNIQUE,
	"id_disciplina" INTEGER NOT NULL,
	PRIMARY KEY("id_turma", "id_disciplina")
);

CREATE TABLE IF NOT EXISTS "coordenador" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"usuario_id" INTEGER NOT NULL UNIQUE,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "administrativo" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"usuario_id" INTEGER NOT NULL UNIQUE,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "cpa_externo" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"usuario_id" INTEGER NOT NULL UNIQUE,
	PRIMARY KEY("id")
);

ALTER TABLE "aluno"
ADD FOREIGN KEY("usuario_id") REFERENCES "usuario"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "matricula"
ADD FOREIGN KEY("aluno_ra") REFERENCES "aluno"("ra")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "matricula"
ADD FOREIGN KEY("turma_id") REFERENCES "turma"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "compoe"
ADD FOREIGN KEY("id_turma") REFERENCES "turma"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "compoe"
ADD FOREIGN KEY("id_disciplina") REFERENCES "disciplina"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "coordenador"
ADD FOREIGN KEY("usuario_id") REFERENCES "usuario"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "cpa_externo"
ADD FOREIGN KEY("usuario_id") REFERENCES "usuario"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "administrativo"
ADD FOREIGN KEY("usuario_id") REFERENCES "usuario"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;